import os, stat, sys
paths = ('/dev/null', '/dev/full')
if sys.argv[1] == 'save':
    values = []
    for path in paths:
        st = os.stat(path)
        if not stat.S_ISCHR(st.st_mode):
            raise SystemExit(98)
        values.append((st.st_dev, st.st_ino, st.st_rdev))
    with open('devices', 'w') as f:
        f.write(repr(values))
else:
    import ast
    with open('devices') as f:
        values = ast.literal_eval(f.read())
    for path, value in zip(paths, values):
        st = os.stat(path)
        if not stat.S_ISCHR(st.st_mode) or (st.st_dev, st.st_ino, st.st_rdev) != value:
            raise SystemExit(1)
    os.unlink('devices')
